<?php
declare(strict_types=1);
require_once __DIR__.'/StaySchema.php';
final class StayVouchers
{
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private static function bad():never{throw new HttpError(400,'Kiểm tra thông tin voucher phòng.');}
    private static function integer(mixed $v,int $min,int $max):int{if(!is_int($v)||$v<$min||$v>$max)self::bad();return $v;}
    private static function uuid(mixed $v):string{if(!is_string($v)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$v))self::bad();return strtolower($v);}
    private static function text(mixed $v,int $max):string{if(!is_string($v)||str_contains($v,"\0"))self::bad();$v=preg_replace('/^[\s\x{FEFF}]+|[\s\x{FEFF}]+$/u','',$v);if($v===null||$v===''||strlen(mb_convert_encoding($v,'UTF-16LE','UTF-8'))/2>$max)self::bad();return $v;}
    public static function validate(array $v):array
    {
        if(array_diff(array_keys($v),['id','version','code','name','type','value','maxDiscount','minSubtotal','minNights','validFrom','validTo','checkInFrom','checkInTo','hotelIds','maxUses','stackWithOffers','enabled']))self::bad();foreach($v as $key=>$value)if($value===null&&!in_array($key,['maxDiscount','maxUses'],true))self::bad();$out=['id'=>self::uuid($v['id'] ?? null),'version'=>self::integer($v['version'] ?? null,0,2147483646),'code'=>mb_strtoupper(self::text($v['code'] ?? null,40),'UTF-8'),'name'=>self::text($v['name'] ?? null,150)];if(!preg_match('/^[A-Z0-9][A-Z0-9_-]{2,39}$/D',$out['code'])||!in_array($v['type'] ?? '',['PERCENT','FIXED'],true))self::bad();$out['type']=$v['type'];$out['value']=self::integer($v['value'] ?? null,1,$v['type']==='PERCENT'?100:100000000);foreach(['maxDiscount'=>15000000000,'maxUses'=>1000000] as $key=>$max)$out[$key]=($v[$key] ?? null)===null?null:self::integer($v[$key],1,$max);$out['minSubtotal']=self::integer($v['minSubtotal'] ?? 0,0,15000000000);$out['minNights']=self::integer($v['minNights'] ?? 1,1,30);foreach(['validFrom','validTo'] as $key)$out[$key]=StaySchema::date($v[$key] ?? null);foreach(['checkInFrom','checkInTo'] as $key)if(array_key_exists($key,$v))$out[$key]=StaySchema::date($v[$key]);if($out['validFrom']>$out['validTo']||isset($out['checkInFrom'],$out['checkInTo'])&&$out['checkInFrom']>$out['checkInTo'])self::bad();$hotels=$v['hotelIds'] ?? [];if(!is_array($hotels)||!array_is_list($hotels)||count($hotels)>200)self::bad();$out['hotelIds']=array_map(self::uuid(...),$hotels);foreach(['stackWithOffers'=>false,'enabled'=>null] as $key=>$default){$value=$v[$key] ?? $default;if(!is_bool($value))self::bad();$out[$key]=$value;}return $out;
    }
    public function list():array{$out=[];foreach($this->query('SELECT id,code,data,version FROM jingo_stay_vouchers ORDER BY code')->fetchAll(PDO::FETCH_ASSOC) as $r)$out[]=array_replace(json_decode($r['data'],true,512,JSON_THROW_ON_ERROR),['id'=>$r['id'],'code'=>$r['code'],'version'=>(int)$r['version']]);return ['data'=>$out];}
    public function save(array $input,string $actor):array
    {
        $v=self::validate($input);$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{if(!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');$old=$this->query('SELECT version FROM jingo_stay_vouchers WHERE id=? FOR UPDATE',[$v['id']])->fetchColumn();if(($old===false?0:(int)$old)!==$v['version'])throw new HttpError(409,'Voucher đã thay đổi. Tải lại trước khi lưu.');foreach(array_unique($v['hotelIds']) as $id)if(!$this->query('SELECT id FROM jingo_stays WHERE id=?',[$id])->fetchColumn())throw new HttpError(400,'Cơ sở trong voucher không tồn tại.');$version=$v['version']+1;unset($v['version']);$json=json_encode($v,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);if($old===false)$this->query('INSERT INTO jingo_stay_vouchers(id,code,data,version) VALUES (?,?,?,?)',[$v['id'],$v['code'],$json,$version]);else $this->query('UPDATE jingo_stay_vouchers SET code=?,data=?,version=? WHERE id=?',[$v['code'],$json,$version,$v['id']]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,'stay.voucher.save',$v['id']]);$this->db->commit();return ['ok'=>true];}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();if($e instanceof PDOException&&$e->getCode()==='23000')throw new HttpError(409,'Mã voucher đã được dùng.');throw $e;}
    }
    public function discount(array $input,array $base,?string $today=null):array
    {
        if(!$this->db->inTransaction())throw new LogicException('Voucher pricing requires a transaction.');if($input['voucherCode']==='')return ['discount'=>0,'total'=>$base['subtotal']];$r=$this->query('SELECT id,data FROM jingo_stay_vouchers WHERE code=?',[$input['voucherCode']])->fetch(PDO::FETCH_ASSOC);$v=$r?json_decode($r['data'],true,512,JSON_THROW_ON_ERROR):null;$today??=(new DateTimeImmutable('now',new DateTimeZone('Asia/Ho_Chi_Minh')))->format('Y-m-d');if(!$v||!$v['enabled']||$today<$v['validFrom']||$today>$v['validTo']||$v['hotelIds']&&!in_array($input['hotelId'],$v['hotelIds'],true)||isset($v['checkInFrom'])&&$input['checkIn']<$v['checkInFrom']||isset($v['checkInTo'])&&$input['checkIn']>$v['checkInTo']||count($base['nights'])<$v['minNights']||$base['subtotal']<$v['minSubtotal'])throw new HttpError(400,'Voucher phòng không hợp lệ hoặc chưa đủ điều kiện.');if(!$v['stackWithOffers']&&array_filter($base['nights'],fn($n)=>$n['discount']>0))throw new HttpError(400,'Voucher này không cộng dồn ưu đãi phòng.');$count=(int)$this->query("SELECT COUNT(*) FROM jingo_stay_bookings WHERE JSON_UNQUOTE(JSON_EXTRACT(data,'$.voucherId'))=? AND status NOT IN ('CANCELLED','EXPIRED')",[$r['id']])->fetchColumn();if($v['maxUses']!==null&&$count>=$v['maxUses'])throw new HttpError(409,'Voucher phòng đã hết lượt.');$discount=min($base['subtotal'],$v['type']==='FIXED'?$v['value']:min(intdiv($base['subtotal']*$v['value'],100),$v['maxDiscount'] ?? $base['subtotal']));return ['discount'=>$discount,'total'=>$base['subtotal']-$discount,'voucherId'=>$r['id']];
    }
}
